#!/usr/bin/env bash
# generate-docs.sh — generated by openapi-integration-creator
#
# Runs tfplugindocs once per resource prefix (scm, ztna, ...).  Each run:
#   1. Writes empty sentinel .md.tmpl files for every OTHER prefix's resources
#      so tfplugindocs skips auto-generating nil-data templates for them
#      (empty content → docTemplate.Render returns nil immediately, no crash).
#   2. Writes docs into a staging dir (docs-<prefix>/) to avoid the tool wiping
#      the previous prefix's output on startup.
#   3. Removes its own sentinels so the next prefix's run starts clean.
# After all runs the staging dirs are merged into docs/.
set -euo pipefail

PREFIXES=("scm" "ztna")

# Format example Terraform files if terraform is available.
if command -v terraform &>/dev/null; then
  terraform fmt -recursive ./examples/ || true
fi

# Collect all type names from the generated source for a given prefix.
collect_types() {
  local prefix="$1"
  grep -rh 'resp\.TypeName = "' internal/provider/ 2>/dev/null \
    | sed 's/.*resp\.TypeName = "//;s/".*//' \
    | grep "^${prefix}_" \
    | sort -u || true
}

for PREFIX in "${PREFIXES[@]}"; do
  echo "📄 Generating docs for prefix: $PREFIX"

  # Write empty sentinel templates for all OTHER prefixes.
  declare -a SENTINELS=()
  for OTHER in "${PREFIXES[@]}"; do
    [ "$OTHER" = "$PREFIX" ] && continue
    while IFS= read -r TYPE; do
      [ -z "$TYPE" ] && continue
      for SUBDIR in resources data-sources; do
        mkdir -p "templates/$SUBDIR"
        SENTINEL="templates/$SUBDIR/${TYPE}.md.tmpl"
        if [ ! -f "$SENTINEL" ]; then
          printf '' > "$SENTINEL"   # empty file — safe for docTemplate.Render(nil)
          SENTINELS+=("$SENTINEL")
        fi
      done
    done < <(collect_types "$OTHER")
  done

  STAGING="docs-${PREFIX}"
  go run github.com/hashicorp/terraform-plugin-docs/cmd/tfplugindocs generate \
    --provider-name "$PREFIX" \
    --rendered-website-dir "$STAGING"

  # Remove sentinels so the next prefix's run starts clean.
  for S in "${SENTINELS[@]+"${SENTINELS[@]}"}"; do
    rm -f "$S"
  done
  unset SENTINELS
done

# Merge staging dirs into docs/, skipping empty files from sentinels.
mkdir -p docs
for PREFIX in "${PREFIXES[@]}"; do
  STAGING="docs-${PREFIX}"
  [ -d "$STAGING" ] || continue
  find "$STAGING" -type f | while read -r SRC; do
    [ -s "$SRC" ] || continue   # skip empty files
    REL="${SRC#${STAGING}/}"
    DST="docs/${REL}"
    mkdir -p "$(dirname "$DST")"
    cp "$SRC" "$DST"
  done
  rm -rf "$STAGING"
done

echo "✅ Documentation generation complete"
